  json: {
    bandIndex: 0,
    band: bands[0],
    bandCount: bands.length,
    page: Number(cfg.startPage) || 1,
    stop: false,
    stopReason: '',
    previousSignature: '',
    consecutiveFailures: 0,
    existingEdbSeeded: sd.stats.existingEdbSeeded
  }
}];

