    parseMkNumber: parseMkNumber,
    cityFromAddress: cityFromAddress,
    extractAddress: extractAddress,
    normalizePhone: normalizePhone,
    isValidMkPhone: isValidMkPhone,
    extractPhones: extractPhones,
    extractEmails: extractEmails,
    extractPeople: extractPeople,
    pickContactPerson: pickContactPerson,
    labelBoundary: labelBoundary,
    extractEmbs: extractEmbs,
    extractEdb: extractEdb,
    extractActivity: extractActivity,
    sliceContactsSection: sliceContactsSection,
    detectBlockedPage: detectBlockedPage,
    normalizeProfilePath: normalizeProfilePath,
    parseSearchResults: parseSearchResults,
    parseProfile: parseProfile,
    parseLica: parseLica,
    buildSearchUrl: buildSearchUrl
  };
}

// ---------------------------------------------------------------------------
// Revenue band partitioning
// ---------------------------------------------------------------------------

/**
 * Split a revenue range into contiguous, non-overlapping sub-ranges whose union
 * is exactly the original range.
 *
 * Why: a single search can only be paged as deep as the site allows. Sweeping the
 * same overall filter in slices keeps each sub-search short enough to reach its
 * own end, so companies past any pagination depth cap become reachable.
 *
 * Spacing is geometric, not linear, because company counts are heavily skewed
 * toward the low end of a revenue range — equal-width bands would put almost
 * everything in the first slice and defeat the point.
 */
function buildRevenueBands(from, to, count) {
  var f = Number(from);
  var t = Number(to);
  var n = Math.floor(Number(count) || 1);

  if (!Number.isFinite(f) || !Number.isFinite(t) || t <= f) return [{ from: f, to: t }];
  if (n <= 1 || f <= 0) return [{ from: f, to: t }];

  var bands = [];
  var ratio = t / f;
  var lo = f;

  for (var i = 1; i <= n; i++) {
    var hi;
    if (i === n) {
      hi = t;
    } else {
      hi = Math.round(f * Math.pow(ratio, i / n)) - 1;
      if (hi > t) hi = t;
    }
    if (hi < lo) continue;
    bands.push({ from: lo, to: hi });
    if (hi >= t) break;
    lo = hi + 1;
  }

  return bands.length ? bands : [{ from: f, to: t }];
}

/**
 * ЕДБ as it is used for de-duplication: digits only.
 *
 * Values read back from Google Sheets may arrive as numbers, or with stray
 * formatting, so both sides of the comparison are reduced to digits.
 */
function normalizeEdb(value) {
  return String(value === null || value === undefined ? '' : value).replace(/\D/g, '');
}

if (typeof module !== 'undefined' && module && module.exports) {
  module.exports.buildRevenueBands = buildRevenueBands;
  module.exports.normalizeEdb = normalizeEdb;
}


// ===== inlined from src/nodes/_http.js =====
/**
 * Shared HTTP-response reader.
 *
 * The ScrapingBee HTTP Request nodes are configured with fullResponse + neverError,
 * so a non-2xx response arrives as a normal item with a statusCode instead of
 * aborting the run. onError=continueRegularOutput covers transport-level failures,
 * which arrive as an item carrying `error`.
 */
function readHttpItem(item) {
  const json = (item && item.json) ? item.json : {};
  const status = (json.statusCode !== undefined && json.statusCode !== null) ? Number(json.statusCode) : null;

  let html = '';
  if (typeof json.body === 'string') html = json.body;
  else if (typeof json.data === 'string') html = json.data;
  else if (typeof json === 'string') html = json;

  let error = '';
  if (json.error) {
    error = typeof json.error === 'string' ? json.error : (json.error.message || JSON.stringify(json.error));
  }
  if (!error && status !== null && status >= 400) {
    error = 'HTTP ' + status + (html ? (' — ' + String(html).slice(0, 200)) : '');
  }
  if (!error && !html) error = 'empty response body';

  return { status, html, error };
}

/** Split a comma/semicolon/newline separated config string into a clean array. */
function splitList(value) {
  if (!value) return [];
  return String(value).split(/[,;\n]/).map((s) => s.trim()).filter(Boolean);
}


// ===== node logic =====
// @requires-parsers
// Fallback only: the profile page listed no Сопственик/Управител at all, so the
// full /lica list is fetched and re-parsed. Everything else on the row is kept.

const record = $('Parse Profile').first().json;
const sd = $getWorkflowStaticData('global');
const stats = sd.stats;

const { status, html, error } = readHttpItem($input.first());

let failure = error;
let parsed = null;

if (!failure) {
  parsed = parseLica(html);
  if (parsed.blocked) failure = parsed.blocked;
}

if (failure || !parsed.contactPerson) {
  if (failure) {
    stats.licaFailures += 1;
    stats.failedUrls.push({
      stage: 'lica',
      edb: record._edb,
      url: record._licaUrl,
      status,
      reason: failure
    });
  }
  // No contact person anywhere — the cell stays blank, the row is still written.
  stats.noContactPerson += 1;
  return [{ json: { ...record, _needsLica: false, _licaFailure: failure || 'no owner/manager listed on /lica either' } }];
}

return [{
  json: {
    ...record,
    _needsLica: false,
    _licaFailure: '',
    _people: parsed.people,
    _contactPersonRole: parsed.contactPersonRole,
    _peopleSource: '/lica fallback',
    'Контакт лице': parsed.contactPerson
  }
}];

